static constexpr size_t AAC_DMA_GUARD_LARGEST_BYTES = 8 * 1024;
static constexpr size_t AUDIO_QUEUE_DEPTH = 8;
static constexpr uint32_t AUDIO_WRITE_STALL_MS = 500;
