class BitReader {
 public:
  BitReader(const uint8_t *data, size_t bits) : data_(data), bits_(bits) {}
  bool read(unsigned n, uint32_t &value) {
    if (n > 32 || pos_ + n > bits_) return false;
    value = 0;
    for (unsigned i = 0; i < n; i++) {
      value = (value << 1) | ((data_[(pos_ + i) >> 3] >> (7 - ((pos_ + i) & 7))) & 1U);
    }
    pos_ += n;
    return true;
  }
 private:
  const uint8_t *data_;
  size_t bits_;
  size_t pos_{0};
};

